({
    width,
    height,
    rows,
    columns,
    padding,
    square,
}: {
    width: number
    height: number
    rows: number
    columns: number
    padding: number
    square: boolean
}) => {
    const cellWidth = (width - (columns - 1) * padding) / columns
    const cellHeight = (height - (rows - 1) * padding) / rows

    if (!square) return [cellWidth, cellHeight]

    const min = Math.min(cellWidth, cellHeight)
    return [min, min]
}

