packages/grid/src/grid.ts:generateGrid.javascript:
(                               ({
    width,
    height,
    columns,
    rows,
    padding = 0,
    fillDirection = 'bottom',
    square = true,
    extend,
}   








 ) => {
    const [cellWidth, cellHeight] = computeCellDimensions({
        width,
        height,
        rows,
        columns,
        padding,
        square,
    })

    const origin         = [
        (width - (cellWidth * columns + padding * (columns - 1))) / 2,
        (height - (cellHeight * rows + padding * (rows - 1))) / 2,
    ]

    const cells             = []

    for (let row = 0; row < rows; row++) {
        for (let column = 0; column < columns; column++) {
            const x = column * cellWidth
            const y = row * cellHeight
            const key = `${row}.${column}`

            cells.push({
                key,
                // Adjusted later depending on `fillDirection`.
                index: 0,
                column,
                row,
                x,
                y,
                width: cellWidth,
                height: cellHeight,
            })
        }
    }

    switch (fillDirection) {
        case 'left':
            cells.sort((a, b) => {
                if (a.column !== b.column) {
                    return b.column - a.column
                }
                return b.row - a.row
            })
            break
        case 'top':
            cells.sort((a, b) => {
                if (a.row !== b.row) {
                    return b.row - a.row
                }
                return b.column - a.column
            })
            break
        case 'right':
            cells.sort((a, b) => {
                if (a.column !== b.column) {
                    return a.column - b.column
                }
                return a.row - b.row
            })
            break

        default: // bottom, nothing to do.
    }

    // Adjust the index depending on `fillDirection`.
    cells.forEach((cell, index) => {
        cell.index = index
    })

    // Optionally "augment" the cells via `extend`.
    const extendedCells      =
        typeof extend === 'function' ? cells.map(cell => extend(cell, origin)) : (cells       )

    return {
        x: origin[0],
        y: origin[1],
        cellWidth,
        cellHeight,
        cells: extendedCells,
    }
})

