({
    width,
    height,
    rows,
    columns,
    fillDirection,
    emptyColor,
    emptyOpacity,
    getBorderColor,
}: {
    width: number
    height: number
    rows: number
    columns: number
    fillDirection: GridFillDirection
    emptyColor: string
    emptyOpacity: number
    getBorderColor: ReturnType<typeof useInheritedColor<{ color: string }>>
}) => {
    const borderColor = getBorderColor({ color: emptyColor })
    const extend = (cell: GridCell, origin: [number, number]): EmptyCell => ({
        ...cell,
        x: origin[0] + cell.x,
        y: origin[1] + cell.y,
        color: emptyColor,
        opacity: emptyOpacity,
        borderColor,
    })

    // We do not apply the padding at this stage so that we can
    // easily compute the polygon surrounding each "area"
    // (all cells belonging to a specific datum), because they
    // need to touch.
    const { cells } = generateGrid<EmptyCell>({
        width,
        height,
        rows,
        columns,
        fillDirection,
        square: true,
        extend,
    })

    return cells
}

