function perpendicularPolygon() {
    const left: Vertex[] = []
    const right: Vertex[] = []

    function polygon() {
        return [...right, ...left]
    }

    polygon.addRight = (...vertices: Vertex[]) => {
        right.push(...vertices)
    }

    polygon.addLeft = (...vertices: Vertex[]) => {
        left.unshift(...vertices)
    }

    polygon.debug = () => {
        return { right, left }
    }

    return polygon
}

